function CustomTextFilterWidget() {
this.getAssociatedTypes = function () { return ["TextFilterWidget"] }; this.onShow = function () { }; this.showClearFilterButton = function () { return !0 }; this.onRender = function (container, lang, typeName, values, cb, data) { this.cb = cb; this.container = container; this.lang = lang; this.value = values.length > 0 ? values[0] : { filterType: 1, filterValue: "" }; this.renderWidget(); this.fillText($.parseJSON(data)); this.registerEvents() }; this.renderWidget = function () {
    var html = '<p><i>This is custom filter widget demo.</i></p>\
                    <p>Select customer to filter:</p>\
                    <select style="width:250px;" class="grid-filter-type list form-control">\
                    </select>'; this.container.append(html)
}; this.fillText = function (items) {
    var List = this.container.find(".list"); var index = List.parents('th').index(); var table = List.parents('table'); if (items == null) {
        $("td:nth-child(" + (index + 1) + ")").each(function (i, el) {
            var x = !0
            List.children('option').each(function (j, option) {
                if (option.innerText == el.firstChild.textContent) { x = !1 }
            }); if (x == !0) { List.append('<option value="' + el.firstChild.textContent + '">' + el.firstChild.textContent + '</option>') }
        })
    }
    else { for (var i = 0; i < items.length; i++) { List.append('<option ' + (items[i] == this.value.filterValue ? 'selected="selected"' : '') + ' value="' + items[i] + '">' + items[i] + '</option>') } }
}; this.registerEvents = function () { var List = this.container.find(".list"); var $context = this; List.change(function () { var values = [{ filterValue: $(this).val(), filterType: 1 }]; $context.cb(values) }) }
}